"""Motion mode end to end: schema generated by make_project (core + motion, optionally + motion_refine) on the
synthetic tutorial data."""
import importlib.util
import os
from pathlib import Path

import numpy as np
import pytest

from tests.fixtures.dj_test_db import new_test_schema

from djimaging.utils.dj_storage import load_array

pytestmark = pytest.mark.skipif(
    os.environ.get("DJ_TEST_MYSQL") != "1",
    reason="requires the MySQL integration-test service",
)

ROOT = Path(__file__).resolve().parents[2]


@pytest.fixture(scope="module", params=[['motion'], ['motion_refine']], ids=['motion', 'motion_refine'])
def motion_schema(request, dj_test_connection, dj_test_stores, tmp_path_factory):
    spec = importlib.util.spec_from_file_location('make_project', ROOT / 'make_project.py')
    make_project = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(make_project)
    module_name = f"motion_schema_{request.param[0]}"
    text = make_project.build_schema_text(ROOT, make_project.resolve_blocks(request.param), channels=None)
    path = tmp_path_factory.mktemp(module_name) / f'{module_name}.py'
    path.write_text(text, encoding='utf8')
    spec = importlib.util.spec_from_file_location(module_name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    with new_test_schema(dj_test_connection, module.schema, request.param[0]):
        yield module


def test_motion_pipeline(motion_schema, tutorial_data_dir):
    s = motion_schema
    refine = hasattr(s, 'RefinedRoiMask')
    experiment_key = {"experimenter": "synthetic"}
    s.UserInfo().upload_user({**experiment_key, "data_dir": str(tutorial_data_dir), "datatype_loc": 0,
                              "animal_loc": 1, "region_loc": 2, "field_loc": 3, "stimulus_loc": 4, "cond1_loc": 5,
                              "cond2_loc": 6, "cond3_loc": 7}, verbose=0)
    s.RawDataParams().add_params(
        from_raw_data=False, igor_roi_masks="yes", experimenter_list=["synthetic"])
    s.Experiment().rescan_filesystem(restrictions=experiment_key, verboselvl=0)
    s.Field().rescan_filesystem(restrictions=experiment_key, verboselvl=0)
    s.Stimulus().add_nostim(skip_duplicates=True)
    s.Stimulus().add_chirp(spatialextent=1000, stim_name="gChirp", alias="chirp_gchirp_globalchirp",
                           skip_duplicates=True)
    s.Stimulus().add_noise(stim_name="noise", pix_n_x=20, pix_n_y=15, pix_scale_x_um=30, pix_scale_y_um=30,
                           skip_duplicates=True)
    s.Stimulus().add_movingbar(skip_duplicates=True)
    s.Presentation().populate(display_progress=False)
    s.RoiMask().rescan_filesystem(restrictions=experiment_key, verboselvl=0, roi_mask_dir="AutoROIs")
    s.Roi().populate(experiment_key, display_progress=False)

    # Motion mode: RoiMask only stores the field mask
    assert s.RoiMask.RoiMaskPresentation is None
    assert len(s.RoiMask() & experiment_key) == 1
    # The presentation of the field mask is chosen by fit and the mask aligned to it; the file is unchanged
    row = (s.RoiMask() & experiment_key).fetch1()
    assert row['mask_selection'] in ('fit', 'alias')
    assert abs(row['align_dx']) <= s.RoiMask._field_mask_max_offset
    assert abs(row['align_dy']) <= s.RoiMask._field_mask_max_offset
    assert s.RoiMask().check_filesystem_consistency(experiment_key, verbose=False) == []

    # The prepared (aligned) field mask is saved to files and the entry references them; the mask is unchanged
    export = s.RoiMask().export_field_roi_masks(experiment_key, roi_mask_dir="PreparedROIs", verbose=False)
    assert export['skipped'] == [] and export['errors'] == [] and len(export['linked']) == 1
    row_exported = (s.RoiMask() & experiment_key).fetch1()
    assert np.array_equal(load_array(row_exported['roi_mask']), load_array(row['roi_mask']))
    assert row_exported['align_dx'] == 0 and row_exported['align_dy'] == 0
    assert row_exported['roi_mask_source'] == 'numpy'
    assert str(row_exported['roi_mask_file']).endswith('_FieldROIs.npy')  # one field mask file, no copies
    assert s.RoiMask().check_filesystem_consistency(experiment_key, verbose=False) == []

    # Deploying the field mask file keeps its presentation and mask (no choice by fit, no alignment)
    field_key = (s.Field() & experiment_key).proj().fetch1()
    s.RoiMask().deploy_roi_mask(field_key, roi_table=s.Roi(), roi_mask_dir="PreparedROIs", verbose=False)
    row_deployed = (s.RoiMask() & experiment_key).fetch1()
    assert row_deployed['mask_selection'] == 'file'
    assert all(row_deployed[k] == row[k] for k in s.Presentation.primary_key)
    assert np.array_equal(load_array(row_deployed['roi_mask']), load_array(row['roi_mask']))
    assert len(s.Roi() & experiment_key) > 0

    s.MotionParams().add(motion_params_id=1)
    s.MotionReference().populate(display_progress=False)
    s.MotionDetection().populate(display_progress=False)
    if refine:
        s.RefinedRoiMask().populate(display_progress=False)
    s.MotionRoiMask().populate(display_progress=False)
    s.MotionTrust().populate(display_progress=False)
    s.Traces().populate(experiment_key, display_progress=False)

    n_pres = len(s.Presentation() & experiment_key)
    n_rois = len(s.Roi() & experiment_key)
    assert len(s.MotionReference()) == 1
    assert len(s.MotionDetection()) == n_pres
    drawn = load_array((s.RoiMask() & experiment_key).fetch1('roi_mask'))
    field_mask = drawn
    if refine:
        # Refined field mask: same ROI ids, borders moved by at most refine_max_px
        assert len(s.RefinedRoiMask()) == 1
        assert len(s.RefinedRoiMask.Roi()) == n_rois
        field_mask = load_array(s.RefinedRoiMask().fetch1('roi_mask'))
        assert set(np.unique(field_mask[field_mask < 0])) == set(np.unique(drawn[drawn < 0]))
        from scipy import ndimage
        for rid in np.unique(drawn[drawn < 0]):
            assert not np.any((field_mask == rid) & ~ndimage.binary_dilation(drawn == rid))
            assert not np.any(ndimage.binary_erosion(drawn == rid) & (field_mask != rid))  # the core is always kept
    assert len(s.MotionRoiMask()) == n_pres
    assert len(s.MotionRoiMask.Roi()) == n_pres * n_rois
    assert len(s.MotionTrust.Roi()) == n_pres * n_rois
    assert len(s.Traces() & experiment_key) == n_pres * n_rois

    # The reference presentation (the one of the field mask) has no shifts and the (refined) field mask as label mask
    ref_row = (s.MotionRoiMask() & 'is_reference').fetch1()
    assert ref_row['shift_dx'] == 0 and ref_row['shift_dy'] == 0
    assert np.array_equal(load_array(ref_row['roi_mask']) < 0, field_mask < 0)
    assert np.allclose((s.MotionRoiMask.Roi() & (s.MotionRoiMask() & 'is_reference')).to_arrays('shift_x'), 0)

    for trace in (s.Traces() & experiment_key).to_arrays('trace'):
        assert np.all(np.isfinite(load_array(trace)))
    trust = (s.MotionTrust() & experiment_key).to_arrays('trust_median')
    assert np.all((trust >= 0) & (trust <= 1))
